const pagerState = ref(null);
const items = ref([]);
const selectedRow = ref(null);
const selectedCol = ref(null);
//----------------------------------------------------------
function pageChanged(pager) {
  pagerState.value = pager;
  getDataSlice();
}
//----------------------------------------------------------
function getDataSlice() {
  let startIndex = (pagerState.value.page-1) * pagerState.value.pageSize;
  let endIndex = startIndex + pagerState.value.pageSize;
  items.value = MOCK_DATA.slice(startIndex, endIndex);  
}
